const pool = require('../config/banco');

async function listarTodos() {
  const [pedidos] = await pool.query(
    `SELECT
      p.*,
      u.nome AS usuario_nome,
      u.email AS usuario_email
    FROM pedidos p
    INNER JOIN usuarios u ON u.id = p.usuario_id
    ORDER BY p.criado_em DESC`
  );

  return pedidos;
}

async function listarPorUsuario(usuarioId) {
  const [pedidos] = await pool.query(
    `SELECT *
    FROM pedidos
    WHERE usuario_id = ?
    ORDER BY criado_em DESC`,
    [usuarioId]
  );

  return pedidos;
}

async function buscarPorId(id) {
  const [pedidos] = await pool.query(
    `SELECT
      p.*,
      u.nome AS usuario_nome,
      u.email AS usuario_email,
      u.cpf AS usuario_cpf
    FROM pedidos p
    INNER JOIN usuarios u ON u.id = p.usuario_id
    WHERE p.id = ?`,
    [id]
  );

  return pedidos[0] || null;
}

async function criar(dadosPedido, conexao = pool) {
  const {
    usuario_id,
    tipo_entrega,
    endereco_entrega,
    telefone_contato,
    subtotal,
    frete,
    desconto,
    total,
    idempotency_key,
  } = dadosPedido;

  const [resultado] = await conexao.query(
    `INSERT INTO pedidos
      (
        usuario_id,
        idempotency_key,
        tipo_entrega,
        endereco_entrega,
        telefone_contato,
        subtotal,
        frete,
        desconto,
        total
      )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)` ,
    [
      usuario_id,
      idempotency_key,
      tipo_entrega,
      endereco_entrega,
      telefone_contato,
      subtotal,
      frete,
      desconto,
      total,
    ]
  );

  return resultado.insertId;
}

async function atualizarStatus(id, paymentStatus, paymentId = null) {
  const [resultado] = await pool.query(
    `UPDATE pedidos
    SET
      payment_status = ?,
      status_pedido = CASE WHEN ? = 'pago' THEN 'pago' WHEN ? = 'cancelado' THEN 'cancelado' ELSE status_pedido END,
      payment_id = COALESCE(?, payment_id)
    WHERE id = ?`,
    [paymentStatus, paymentStatus, paymentStatus, paymentId, id]
  );

  return resultado.affectedRows;
}

async function confirmarPagamento(id, paymentId, itens, estoqueService) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT payment_status FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );
    const pedido = pedidos[0];

    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (pedido.payment_status === 'pago') {
      await conexao.commit();
      return true;
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'pago', status_pedido = 'pago', payment_id = COALESCE(?, payment_id)
       WHERE id = ?`,
      [paymentId, id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function atualizarRastreio(id, codigoRastreio) {
  const [resultado] = await pool.query(
    `UPDATE pedidos
     SET codigo_rastreio = ?
     WHERE id = ?`,
    [codigoRastreio || null, id]
  );

  return resultado.affectedRows;
}

async function cancelarPedido(id) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT * FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );

    const pedido = pedidos[0];
    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (pedido.status_pedido === 'cancelado') {
      await conexao.commit();
      return false;
    }

    const [itens] = await conexao.query(
      'SELECT produto_id, quantidade FROM itens_pedido WHERE pedido_id = ?',
      [id]
    );

    if (pedido.estoque_reservado) {
      for (const item of itens) {
      await conexao.query(
        'UPDATE produtos SET estoque_qtd = estoque_qtd + ? WHERE id = ?',
        [item.quantidade, item.produto_id]
      );
      }
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'cancelado',
           status_pedido = CASE WHEN payment_id IS NULL THEN 'cancelado' ELSE 'reembolso_pendente' END,
           estoque_reservado = FALSE
       WHERE id = ?`,
      [id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function buscarPorIdempotency(usuarioId, idempotencyKey, conexao = pool) {
  const [pedidos] = await conexao.query(
    'SELECT * FROM pedidos WHERE usuario_id = ? AND idempotency_key = ?',
    [usuarioId, idempotencyKey]
  );
  return pedidos[0] || null;
}

async function registrarWebhook(eventoId, tipo) {
  try {
    await pool.query(
      'INSERT INTO webhook_eventos (evento_id, tipo) VALUES (?, ?)',
      [eventoId, tipo]
    );
    return true;
  } catch (erro) {
    if (erro.code === 'ER_DUP_ENTRY') return false;
    throw erro;
  }
}

async function marcarReembolsoPendente(id) {
  await pool.query(
    `UPDATE pedidos SET status_pedido = 'reembolso_pendente' WHERE id = ? AND payment_status = 'cancelado'`,
    [id]
  );
}

async function relatorioMensal() {
  const [resultado] = await pool.query(
    `SELECT
      COALESCE(SUM(total), 0) AS total_vendido,
      COUNT(*) AS quantidade_pedidos
    FROM pedidos
    WHERE payment_status = 'pago'
      AND MONTH(criado_em) = MONTH(CURDATE())
      AND YEAR(criado_em) = YEAR(CURDATE())`
  );

  return resultado[0];
}

module.exports = {
  listarTodos,
  listarPorUsuario,
  buscarPorId,
  criar,
  atualizarStatus,
  confirmarPagamento,
  atualizarRastreio,
  cancelarPedido,
  buscarPorIdempotency,
  registrarWebhook,
  marcarReembolsoPendente,
  relatorioMensal,
};

const pool = require('../config/banco');
const Pedido = require('../models/Pedido');
const ItemPedido = require('../models/ItemPedido');
const Log = require('../models/Log');

const tiposEntregaPermitidos = ['envio', 'entrega_local'];

const statusPermitidos = [
  'pendente',
  'pago',
  'recusado',
  'cancelado',
];

async function listar(req, res) {
  try {
    const pedidos = await Pedido.listarTodos();
    res.json(pedidos);
  } catch (erro) {
    res.status(500).json({ mensagem: erro.message });
  }
}

async function listarPorUsuario(req, res) {
