    await conexao.beginTransaction();
    const [usuarios] = await conexao.query(
      'SELECT id, anonimizado_em FROM usuarios WHERE id = ? FOR UPDATE',
      [id]
    );

    if (!usuarios[0]) return false;
    if (usuarios[0].anonimizado_em) {
      await conexao.commit();
      return true;
