const pool = require('../config/banco');

async function listarTodos() {
  const [pedidos] = await pool.query(
    `SELECT
      p.*,
      u.nome AS usuario_nome,
      u.email AS usuario_email
    FROM pedidos p
    INNER JOIN usuarios u ON u.id = p.usuario_id
    ORDER BY p.criado_em DESC`
  );

  return pedidos;
}

async function listarPorUsuario(usuarioId) {
  const [pedidos] = await pool.query(
    `SELECT *
    FROM pedidos
    WHERE usuario_id = ?
    ORDER BY criado_em DESC`,
    [usuarioId]
  );

  return pedidos;
}

async function buscarPorId(id) {
  const [pedidos] = await pool.query(
    `SELECT
      p.*,
      u.nome AS usuario_nome,
      u.email AS usuario_email,
      u.cpf AS usuario_cpf
    FROM pedidos p
    INNER JOIN usuarios u ON u.id = p.usuario_id
    WHERE p.id = ?`,
    [id]
  );

  return pedidos[0] || null;
}

async function criar(dadosPedido, conexao = pool) {
  const {
    usuario_id,
    tipo_entrega,
    endereco_entrega,
    telefone_contato,
    subtotal,
    frete,
    desconto,
    codigo_promocao,
    total,
    idempotency_key,
  } = dadosPedido;

  const [resultado] = await conexao.query(
    `INSERT INTO pedidos
      (
        usuario_id,
        idempotency_key,
        tipo_entrega,
        endereco_entrega,
        telefone_contato,
        subtotal,
        frete,
        desconto,
        codigo_promocao,
        total
      )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)` ,
    [
      usuario_id,
      idempotency_key,
      tipo_entrega,
      endereco_entrega,
      telefone_contato,
      subtotal,
      frete,
      desconto,
      codigo_promocao,
      total,
    ]
  );

  return resultado.insertId;
}

async function atualizarStatus(id, paymentStatus, paymentId = null) {
  const [resultado] = await pool.query(
    `UPDATE pedidos
    SET
      payment_status = ?,
      status_pedido = CASE WHEN ? = 'pago' THEN 'pago' WHEN ? = 'cancelado' THEN 'cancelado' ELSE status_pedido END,
      payment_id = COALESCE(?, payment_id)
    WHERE id = ?`,
    [paymentStatus, paymentStatus, paymentStatus, paymentId, id]
  );

  return resultado.affectedRows;
}

async function confirmarPagamento(id, paymentId, itens, estoqueService) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT payment_status FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );
    const pedido = pedidos[0];

    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (pedido.payment_status === 'pago') {
      await conexao.commit();
      return true;
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'pago', status_pedido = 'pago', payment_id = COALESCE(?, payment_id)
       WHERE id = ?`,
      [paymentId, id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function atualizarRastreio(id, codigoRastreio) {
  const [resultado] = await pool.query(
    `UPDATE pedidos
     SET codigo_rastreio = ?
     WHERE id = ?`,
    [codigoRastreio || null, id]
  );

  return resultado.affectedRows;
}

async function cancelarPedido(id) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT * FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );

    const pedido = pedidos[0];
    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (pedido.status_pedido === 'cancelado') {
      await conexao.commit();
      return false;
    }

    const [itens] = await conexao.query(
      'SELECT produto_id, quantidade FROM itens_pedido WHERE pedido_id = ?',
      [id]
    );

    if (pedido.estoque_reservado) {
      for (const item of itens) {
      await conexao.query(
        'UPDATE produtos SET estoque_qtd = estoque_qtd + ? WHERE id = ?',
        [item.quantidade, item.produto_id]
      );
      }
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'cancelado',
           status_pedido = CASE WHEN payment_id IS NULL THEN 'cancelado' ELSE 'reembolso_pendente' END,
           estoque_reservado = FALSE
       WHERE id = ?`,
      [id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function buscarPorIdempotency(usuarioId, idempotencyKey, conexao = pool) {
  const [pedidos] = await conexao.query(
    'SELECT * FROM pedidos WHERE usuario_id = ? AND idempotency_key = ?',
    [usuarioId, idempotencyKey]
  );
  return pedidos[0] || null;
}

async function registrarWebhook(eventoId, tipo) {
  try {
    await pool.query(
      'INSERT INTO webhook_eventos (evento_id, tipo) VALUES (?, ?)',
      [eventoId, tipo]
    );
    return true;
  } catch (erro) {
    if (erro.code === 'ER_DUP_ENTRY') return false;
    throw erro;
  }
}

async function marcarReembolsoPendente(id) {
  await pool.query(
    `UPDATE pedidos SET status_pedido = 'reembolso_pendente' WHERE id = ? AND payment_status = 'cancelado'`,
    [id]
  );
}

async function relatorioMensal() {
  const [resultado] = await pool.query(
    `SELECT
      COALESCE(SUM(total), 0) AS total_vendido,
      COUNT(*) AS quantidade_pedidos
    FROM pedidos
    WHERE payment_status = 'pago'
      AND MONTH(criado_em) = MONTH(CURDATE())
      AND YEAR(criado_em) = YEAR(CURDATE())`
  );

  return resultado[0];
}

module.exports = {
  listarTodos,
  listarPorUsuario,
  buscarPorId,
  criar,
  atualizarStatus,
  confirmarPagamento,
  atualizarRastreio,
  cancelarPedido,
  buscarPorIdempotency,
  registrarWebhook,
  marcarReembolsoPendente,
  relatorioMensal,
};

const pool = require('../config/banco');
const Pedido = require('../models/Pedido');
const ItemPedido = require('../models/ItemPedido');
const Log = require('../models/Log');
const Promocao = require('../models/Promocao');

const tiposEntregaPermitidos = ['envio', 'entrega_local'];

const statusPermitidos = [
  'pendente',
  'pago',
  'recusado',
  'cancelado',
];

async function listar(req, res) {
  try {
    const pedidos = await Pedido.listarTodos();
    res.json(pedidos);
  } catch (erro) {
    res.status(500).json({ mensagem: erro.message });
  }
}

async function listarPorUsuario(req, res) {
  try {
    const usuarioId = req.usuario.perfil === 'admin'
      ? req.params.usuarioId
      : req.usuario.id;

    const pedidos = await Pedido.listarPorUsuario(
      usuarioId
    );

    res.json(pedidos);
  } catch (erro) {
    res.status(500).json({ mensagem: erro.message });
  }
}

async function buscar(req, res) {
  try {
    const pedido = await Pedido.buscarPorId(req.params.id);

    if (!pedido) {
      return res.status(404).json({
        mensagem: 'Pedido não encontrado',
      });
    }

    if (
      req.usuario.perfil !== 'admin'
      && String(pedido.usuario_id) !== String(req.usuario.id)
    ) {
      return res.status(403).json({
        mensagem: 'Você não tem acesso a este pedido',
      });
    }

    pedido.itens = await ItemPedido.listarPorPedido(pedido.id);

    return res.json(pedido);
  } catch (erro) {
    return res.status(500).json({
      mensagem: erro.message,
    });
  }
}

async function criar(req, res) {
  const {
    tipo_entrega,
    endereco_entrega,
    telefone_contato,
    itens,
    codigo_promocao,
  } = req.body;
  const idempotencyKey = String(req.headers['idempotency-key'] || '').trim();

  if (!idempotencyKey || idempotencyKey.length > 100) {
    return res.status(400).json({ mensagem: 'O header Idempotency-Key é obrigatório' });
  }

  if (
    !tipo_entrega ||
    !endereco_entrega ||
    !telefone_contato
  ) {
    return res.status(400).json({
      mensagem: 'Preencha os dados obrigatórios do pedido',
    });
  }

  if (!tiposEntregaPermitidos.includes(tipo_entrega)) {
    return res.status(400).json({
      mensagem: 'Tipo de entrega inválido',
    });
  }

  if (!Array.isArray(itens) || itens.length === 0) {
    return res.status(400).json({
      mensagem: 'O pedido precisa possuir pelo menos um item',
    });
  }

  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const pedidoExistente = await Pedido.buscarPorIdempotency(
      req.usuario.id,
      idempotencyKey,
      conexao
    );

    if (pedidoExistente) {
      await conexao.commit();
      return res.status(200).json({
        id: pedidoExistente.id,
        total: Number(pedidoExistente.total).toFixed(2),
        status_pedido: pedidoExistente.status_pedido,
        mensagem: 'Pedido já criado',
      });
    }

    const itensPreparados = [];
    let total = 0;

    for (const item of itens) {
      const produtoId = Number(item.produto_id);
      const quantidade = Number(item.quantidade);
      const precoInformado = item.preco_unitario != null ? Number(item.preco_unitario) : null;

      if (
        !Number.isInteger(produtoId) ||
        produtoId <= 0 ||
        !Number.isInteger(quantidade) ||
        quantidade <= 0
      ) {
        throw new Error('Produto ou quantidade inválidos');
      }

      const [produtos] = await conexao.query(
        `SELECT id, preco, estoque_qtd, ativo
        FROM produtos
        WHERE id = ?
        FOR UPDATE`,
        [produtoId]
      );

      const produto = produtos[0];

      if (!produto) {
        throw new Error(`Produto ${produtoId} não encontrado`);
      }

      if (produto.ativo === 0 || produto.ativo === false) {
        throw new Error(`Produto ${produtoId} indisponível no momento`);
      }

      if (produto.estoque_qtd < quantidade) {
        throw new Error(
          `Estoque insuficiente para o produto ${produtoId}`
        );
      }

      if (precoInformado != null && Math.abs(precoInformado - Number(produto.preco)) > 0.01) {
        throw new Error(`Preço do produto ${produtoId} foi alterado e precisa ser revalidado`);
      }

      const precoUnitario = Number(produto.preco);

      const estoqueReservado = await conexao.query(
        `UPDATE produtos
         SET estoque_qtd = estoque_qtd - ?
         WHERE id = ? AND estoque_qtd >= ?`,
        [quantidade, produtoId, quantidade]
      );

      if (!estoqueReservado[0].affectedRows) {
        throw new Error(`Estoque insuficiente para o produto ${produtoId}`);
      }

      total += precoUnitario * quantidade;

      itensPreparados.push({
        produto_id: produtoId,
        quantidade,
        preco_unitario: precoUnitario,
      });

    }

    const [configuracoes] = await conexao.query(
      'SELECT frete_fixo FROM configuracoes_loja WHERE id = 1 FOR SHARE'
    );
    const subtotal = Number(total.toFixed(2));
    let promocao = null;
    let desconto = 0;

    if (codigo_promocao) {
      promocao = await Promocao.buscarValida(codigo_promocao.toUpperCase(), conexao);
      if (!promocao) throw new Error('Código de promoção inválido ou expirado');
      desconto = promocao.tipo === 'percentual'
        ? subtotal * (Number(promocao.valor) / 100)
        : Number(promocao.valor);
      desconto = Math.min(subtotal, Number(desconto.toFixed(2)));
    }

    const frete = tipo_entrega === 'envio'
      ? Number(configuracoes[0]?.frete_fixo || 0)
      : 0;
    const totalPedido = subtotal + frete - desconto;

    if (promocao) await Promocao.incrementarUso(promocao.id, conexao);

    const pedidoId = await Pedido.criar(
      {
        usuario_id: req.usuario.id,
        tipo_entrega,
        endereco_entrega,
        telefone_contato,
        subtotal: subtotal.toFixed(2),
        frete: frete.toFixed(2),
        desconto: desconto.toFixed(2),
        codigo_promocao: promocao?.codigo || null,
        total: totalPedido.toFixed(2),
        idempotency_key: idempotencyKey,
      },
      conexao
    );

    await ItemPedido.criarVarios(
      pedidoId,
      itensPreparados,
      conexao
    );

    await Log.registrar({
      tipo: 'pedido',
      acao: 'criado',
      entidade_id: pedidoId,
      usuario_id: req.usuario.id,
      detalhes: { itens: itensPreparados },
    });

    await conexao.commit();

    return res.status(201).json({
      id: pedidoId,
      subtotal: subtotal.toFixed(2),
      frete: frete.toFixed(2),
      desconto: desconto.toFixed(2),
      total: totalPedido.toFixed(2),
      mensagem: 'Pedido criado com sucesso',
    });
  } catch (erro) {
    await conexao.rollback();

    if (erro.code === 'ER_DUP_ENTRY') {
      const pedidoExistente = await Pedido.buscarPorIdempotency(
        req.usuario.id,
        idempotencyKey
      );

      if (pedidoExistente) {
        return res.status(200).json({
          id: pedidoExistente.id,
          total: Number(pedidoExistente.total).toFixed(2),
          status_pedido: pedidoExistente.status_pedido,
          mensagem: 'Pedido já criado',
        });
      }
    }

    return res.status(400).json({
      mensagem: erro.message,
    });
  } finally {
    conexao.release();
  }
}

async function atualizarStatus(req, res) {
  const { payment_status, payment_id } = req.body;

  if (!statusPermitidos.includes(payment_status)) {
    return res.status(400).json({
      mensagem: 'Status de pagamento inválido',
    });
  }

  try {
    const linhasAlteradas = await Pedido.atualizarStatus(
      req.params.id,
      payment_status,
      payment_id
    );

    if (!linhasAlteradas) {
      return res.status(404).json({
        mensagem: 'Pedido não encontrado',
      });
    }

    await Log.registrar({
      tipo: 'pedido',
      acao: 'status_atualizado',
      entidade_id: req.params.id,
      usuario_id: req.usuario.id,
      detalhes: { payment_status, payment_id },
    });

    return res.json({
      mensagem: 'Status do pedido atualizado',
    });
  } catch (erro) {
    return res.status(500).json({
      mensagem: erro.message,
    });
  }
}

async function atualizarRastreio(req, res) {
  const { codigo_rastreio } = req.body;

  try {
    const alterados = await Pedido.atualizarRastreio(
      req.params.id,
      codigo_rastreio
    );

    if (!alterados) {
      return res.status(404).json({
        mensagem: 'Pedido não encontrado',
      });
    }

    await Log.registrar({
      tipo: 'pedido',
      acao: 'rastreio_atualizado',
      entidade_id: req.params.id,
      usuario_id: req.usuario.id,
      detalhes: { codigo_rastreio },
    });

    res.json({ mensagem: 'Código de rastreio atualizado' });
  } catch (erro) {
    res.status(500).json({ mensagem: erro.message });
  }
}

async function cancelar(req, res) {
  try {
    const pedido = await Pedido.buscarPorId(req.params.id);

    if (!pedido) {
      return res.status(404).json({ mensagem: 'Pedido não encontrado' });
    }

    if (req.usuario.perfil !== 'admin' && String(pedido.usuario_id) !== String(req.usuario.id)) {
      return res.status(403).json({ mensagem: 'Você não tem acesso a este pedido' });
    }

    const pedidoCancelado = await Pedido.cancelarPedido(pedido.id);

    let reembolsoPendente = false;
    if (pedidoCancelado && pedido.payment_id) {
      try {
        const mercadoPagoService = require('../services/mercadoPagoService');
        await mercadoPagoService.solicitarReembolso(pedido.payment_id);
        await Pedido.atualizarStatus(pedido.id, 'cancelado', pedido.payment_id);
      } catch (erro) {
        reembolsoPendente = true;
        await Pedido.marcarReembolsoPendente(pedido.id);
        console.warn('Reembolso do Mercado Pago pendente:', erro.message);
      }
    }

    await Log.registrar({
      tipo: 'pedido',
      acao: 'cancelado',
      entidade_id: pedido.id,
      usuario_id: req.usuario.id,
      detalhes: { payment_id: pedido.payment_id },
    });

    return res.json({ mensagem: pedidoCancelado
      ? (reembolsoPendente ? 'Pedido cancelado; reembolso pendente' : 'Pedido cancelado com sucesso')
      : 'Pedido já estava cancelado' });
  } catch (erro) {
    console.error('Erro ao cancelar pedido:', erro);
    return res.status(500).json({ mensagem: erro.message });
  }
}

module.exports = {
  listar,
  listarPorUsuario,
  buscar,
  criar,
  atualizarStatus,
  atualizarRastreio,
  cancelar,
};

