      idempotency_key,
      tipo_entrega,
      endereco_entrega,
      telefone_contato,
      subtotal,
      frete,
      desconto,
      codigo_promocao,
      total,
    ]
  );

  return resultado.insertId;
}

async function atualizarStatus(id, paymentStatus, paymentId = null) {
