async function atualizarStatus(id, paymentStatus, paymentId = null) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();
    const [pedidos] = await conexao.query(
      'SELECT * FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );
    const pedido = pedidos[0];

    if (!pedido) {
      await conexao.rollback();
      return 0;
    }

    if (pedido.payment_status === paymentStatus && (!paymentId || pedido.payment_id === paymentId)) {
      await conexao.commit();
      return 1;
    }

    if (['recusado', 'cancelado'].includes(paymentStatus) && pedido.estoque_reservado) {
      const [itens] = await conexao.query(
        'SELECT produto_id, quantidade FROM itens_pedido WHERE pedido_id = ?',
        [id]
      );
      for (const item of itens) {
        await conexao.query(
          'UPDATE produtos SET estoque_qtd = estoque_qtd + ? WHERE id = ?',
          [item.quantidade, item.produto_id]
        );
      }
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = ?,
           status_pedido = CASE WHEN ? = 'cancelado' THEN 'cancelado' WHEN ? = 'recusado' THEN 'cancelado' ELSE status_pedido END,
           estoque_reservado = CASE WHEN ? IN ('recusado', 'cancelado') THEN FALSE ELSE estoque_reservado END,
           payment_id = COALESCE(?, payment_id)
       WHERE id = ?`,
      [paymentStatus, paymentStatus, paymentStatus, paymentStatus, paymentId, id]
    );
    await conexao.commit();
    return 1;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function atualizarStatusOperacional(id, novoStatus) {
  const transicoes = {
    pago: ['em_preparacao', 'cancelado'],
    em_preparacao: ['enviado', 'cancelado'],
    enviado: ['entregue'],
    reembolso_pendente: ['reembolsado'],
  };
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();
    const [pedidos] = await conexao.query(
      'SELECT status_pedido FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );
    const pedido = pedidos[0];

    if (!pedido) {
      await conexao.rollback();
      return { encontrado: false };
    }

    if (!transicoes[pedido.status_pedido]?.includes(novoStatus)) {
      await conexao.rollback();
      return { encontrado: true, permitido: false, atual: pedido.status_pedido };
    }

    await conexao.query(
      'UPDATE pedidos SET status_pedido = ? WHERE id = ?',
      [novoStatus, id]
    );
    await conexao.commit();
    return { encontrado: true, permitido: true, atual: novoStatus };
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function confirmarPagamento(id, paymentId, itens, estoqueService) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT payment_status FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );
    const pedido = pedidos[0];

    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (
      pedido.payment_status === 'pago'
      || ['cancelado', 'reembolso_pendente', 'reembolsado'].includes(pedido.status_pedido)
    ) {
      await conexao.commit();
      return pedido.payment_status === 'pago';
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'pago', status_pedido = 'pago', payment_id = COALESCE(?, payment_id)
       WHERE id = ?`,
      [paymentId, id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function atualizarRastreio(id, codigoRastreio) {
  const [resultado] = await pool.query(
    `UPDATE pedidos
     SET codigo_rastreio = ?
     WHERE id = ?`,
    [codigoRastreio || null, id]
  );

  return resultado.affectedRows;
}

async function cancelarPedido(id) {
  const conexao = await pool.getConnection();

  try {
    await conexao.beginTransaction();

    const [pedidos] = await conexao.query(
      'SELECT * FROM pedidos WHERE id = ? FOR UPDATE',
      [id]
    );

    const pedido = pedidos[0];
    if (!pedido) {
      await conexao.rollback();
      return false;
    }

    if (pedido.status_pedido === 'cancelado') {
      await conexao.commit();
      return false;
    }

    const [itens] = await conexao.query(
      'SELECT produto_id, quantidade FROM itens_pedido WHERE pedido_id = ?',
      [id]
    );

    if (pedido.estoque_reservado) {
      for (const item of itens) {
      await conexao.query(
        'UPDATE produtos SET estoque_qtd = estoque_qtd + ? WHERE id = ?',
        [item.quantidade, item.produto_id]
      );
      }
    }

    await conexao.query(
      `UPDATE pedidos
       SET payment_status = 'cancelado',
           status_pedido = CASE WHEN payment_id IS NULL THEN 'cancelado' ELSE 'reembolso_pendente' END,
           estoque_reservado = FALSE
       WHERE id = ?`,
      [id]
    );

    await conexao.commit();
    return true;
  } catch (erro) {
    await conexao.rollback();
    throw erro;
  } finally {
    conexao.release();
  }
}

async function buscarPorIdempotency(usuarioId, idempotencyKey, conexao = pool) {
  const [pedidos] = await conexao.query(
    'SELECT * FROM pedidos WHERE usuario_id = ? AND idempotency_key = ?',
    [usuarioId, idempotencyKey]
  );
  return pedidos[0] || null;
}

async function registrarWebhook(eventoId, tipo) {
  try {
    await pool.query(
      'INSERT INTO webhook_eventos (evento_id, tipo) VALUES (?, ?)',
      [eventoId, tipo]
    );
    return true;
  } catch (erro) {
    if (erro.code === 'ER_DUP_ENTRY') return false;
    throw erro;
  }
}

async function marcarReembolsoPendente(id) {
  await pool.query(
    `UPDATE pedidos SET status_pedido = 'reembolso_pendente' WHERE id = ? AND payment_status = 'cancelado'`,
    [id]
  );
}

async function relatorioMensal() {
  const [resultado] = await pool.query(
    `SELECT
      COALESCE(SUM(total), 0) AS total_vendido,
      COUNT(*) AS quantidade_pedidos
    FROM pedidos
    WHERE payment_status = 'pago'
      AND MONTH(criado_em) = MONTH(CURDATE())
      AND YEAR(criado_em) = YEAR(CURDATE())`
  );

  return resultado[0];
}

module.exports = {
  listarTodos,
  listarPorUsuario,
  buscarPorId,
  criar,
  atualizarStatus,
  atualizarStatusOperacional,
  confirmarPagamento,
  atualizarRastreio,
  cancelarPedido,
  buscarPorIdempotency,
  registrarWebhook,
  marcarReembolsoPendente,
  relatorioMensal,
};

const crypto = require('crypto');
const Pedido = require('../models/Pedido');
const ItemPedido = require('../models/ItemPedido');
const Log = require('../models/Log');
const estoqueService = require('../services/estoqueService');
const mercadoPagoService = require('../services/mercadoPagoService');

function validarAssinaturaWebhook(req) {
  const assinatura = String(req.headers['x-signature'] || '').trim();
  const requestId = String(req.headers['x-request-id'] || '').trim();
  const secret = process.env.MERCADOPAGO_WEBHOOK_SECRET;

  if (!secret) {
    throw new Error('MERCADOPAGO_WEBHOOK_SECRET não configurado');
  }

  if (!assinatura) {
    throw new Error('Assinatura do webhook ausente');
  }

  const partes = Object.fromEntries(assinatura.split(',').map((parte) => parte.split('=').map((valor) => valor.trim())));
  const dataId = String(req.query?.['data.id'] || req.body?.data?.id || '').toLowerCase();
  const ts = partes.ts;
  const v1 = partes.v1;

  if (!requestId || !dataId || !ts || !v1) {
    const payload = Buffer.isBuffer(req.body)
      ? req.body
      : Buffer.from(JSON.stringify(req.body || {}));
    const hashLegado = crypto.createHmac('sha256', secret).update(payload).digest('hex');
    const assinaturaLegado = assinatura.replace(/^v1=/, '');
    const assinaturaBuffer = Buffer.from(assinaturaLegado);
    const hashBuffer = Buffer.from(hashLegado);

    if (
      assinaturaBuffer.length !== hashBuffer.length
      || !crypto.timingSafeEqual(hashBuffer, assinaturaBuffer)
    ) {
      throw new Error('Assinatura do webhook inválida');
    }

    return;
  }

  const manifesto = `id:${dataId};request-id:${requestId};ts:${ts};`;
  const hash = crypto.createHmac('sha256', secret).update(manifesto).digest('hex');
  const assinaturaNormalizada = v1;

  const assinaturaBuffer = Buffer.from(assinaturaNormalizada);
  const hashBuffer = Buffer.from(hash);

  if (assinaturaBuffer.length !== hashBuffer.length || !crypto.timingSafeEqual(hashBuffer, assinaturaBuffer)) {
    throw new Error('Assinatura do webhook inválida');
  }
}

async function criarPagamento(req, res) {
  try {
    const pedido = await Pedido.buscarPorId(req.params.pedidoId);

    if (!pedido) {
      return res.status(404).json({ mensagem: 'Pedido não encontrado' });
    }

    if (
      req.usuario.perfil !== 'admin'
      && String(pedido.usuario_id) !== String(req.usuario.id)
    ) {
      return res.status(403).json({
        mensagem: 'Você não tem acesso a este pedido',
      });
    }

    const itens = await ItemPedido.listarPorPedido(pedido.id);
    const order = await mercadoPagoService.criarOrder(pedido, itens);

    res.json(order);
} catch (erro) {
  console.error('Erro completo:', JSON.stringify(erro, null, 2));
  console.error('apiResponse:', erro.apiResponse);
  const status = erro.message.startsWith('Mercado Pago') ? 502 : 500;
  res.status(status).json({ mensagem: erro.message });
}
}
async function receberWebhook(req, res) {
  try {
    const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(JSON.stringify(req.body || {}));
    validarAssinaturaWebhook({ headers: req.headers, body: rawBody });

    const orderId = req.query['data.id'];
    const eventoId = `${req.headers['x-request-id'] || req.query.type || 'evento'}:${orderId}:${req.headers['x-signature'] || 'sem-assinatura'}`;

    console.log('Webhook Mercado Pago recebido:', {
      tipo: req.query.type,
      orderId,
    });

    if (!orderId) {
      return res.status(400).send();
    }

    const order = await mercadoPagoService.buscarOrder(orderId);
    const pedidoId = order.external_reference;

    console.log('Order Mercado Pago consultada:', {
      orderId,
      pedidoId,
      status: order.status,
    });

    if (!pedidoId || !order.status) {
      return res.status(400).send();
    }

    if (!await Pedido.registrarWebhook(eventoId, req.query.type || 'desconhecido')) {
      return res.status(200).send();
    }

    const itens = await ItemPedido.listarPorPedido(pedidoId);

    if (order.status === 'processed') {
      const confirmado = await Pedido.confirmarPagamento(
        pedidoId,
        order.id,
        itens,
        estoqueService
      );

      if (confirmado) {
        await Log.registrar({
          tipo: 'pedido',
          acao: 'pagamento_confirmado',
          entidade_id: pedidoId,
          detalhes: { payment_id: order.id, status: order.status },
        });
      }
    } else {
      const statusTraduzido = {
        cancelled: 'cancelado',
        refused: 'recusado',
      }[order.status];

      if (statusTraduzido) {
        await Pedido.atualizarStatus(pedidoId, statusTraduzido, order.id);

        await Log.registrar({
          tipo: 'pedido',
          acao: 'status_atualizado',
          entidade_id: pedidoId,
          detalhes: { payment_id: order.id, novo_status: statusTraduzido },
        });
      }
    }

    res.status(200).send();
  } catch (erro) {
    console.error('Erro no webhook:', erro);
    if (erro.message && /assinatura|configurado|ausente/i.test(erro.message)) {
      return res.status(401).json({ mensagem: erro.message });
    }
    res.status(500).send();
  }
}

async function sincronizarPagamento(req, res) {
  try {
    const pedido = await Pedido.buscarPorId(req.params.pedidoId);
    const paymentId = req.body?.payment_id
      || req.body?.collection_id
      || req.query.payment_id
      || req.query.collection_id;

    if (!paymentId) {
      return res.status(400).json({ mensagem: 'payment_id não informado' });
    }

    if (!pedido) {
      return res.status(404).json({ mensagem: 'Pedido não encontrado' });
    }

    if (req.usuario.perfil !== 'admin'
      && String(pedido.usuario_id) !== String(req.usuario.id)) {
      return res.status(403).json({ mensagem: 'Você não tem acesso a este pedido' });
    }

    const pagamento = await mercadoPagoService.buscarPagamento(paymentId);

    if (!pagamento || String(pagamento.external_reference) !== String(pedido.id)) {
      return res.status(404).json({ mensagem: 'Pagamento não pertence a este pedido' });
    }

    if (pagamento.status === 'approved') {
      const itens = await ItemPedido.listarPorPedido(pedido.id);
      await Pedido.confirmarPagamento(
        pedido.id,
        String(pagamento.id),
        itens,
        estoqueService
      );
    }

    const statusTraduzido = {
      rejected: 'recusado',
      cancelled: 'cancelado',
    }[pagamento.status];

    if (statusTraduzido) {
      await Pedido.atualizarStatus(
        pedido.id,
        statusTraduzido,
        String(pagamento.id)
      );
    }

    return res.json({
      status: pagamento.status,
      payment_status: statusTraduzido || pagamento.status,
    });
  } catch (erro) {
    console.error('Erro ao sincronizar pagamento:', erro);

    if (erro.message.startsWith('Estoque insuficiente')) {
      return res.status(409).json({ mensagem: erro.message });
    }

    if (erro.message.startsWith('Mercado Pago')) {
      return res.status(502).json({ mensagem: erro.message });
    }

    return res.status(500).json({ mensagem: 'Erro ao sincronizar pagamento' });
  }
}

module.exports = { criarPagamento, receberWebhook, sincronizarPagamento };

const API_URL = import.meta.env.VITE_API_URL || '/api';

function headersComToken() {
  const token = localStorage.getItem('token');
  return {
    'Content-Type': 'application/json',
    Authorization: token ? `Bearer ${token}` : '',
  };
}

export async function criarPedido(dadosPedido, idempotencyKey) {
  const resposta = await fetch(`${API_URL}/pedidos`, {
    method: 'POST',
    headers: {
      ...headersComToken(),
      'Idempotency-Key': idempotencyKey,
    },
    body: JSON.stringify(dadosPedido),
  });

  if (!resposta.ok) {
    const erro = await resposta.json();
    throw new Error(erro.mensagem || 'Erro ao processar o pedido');
  }

  return await resposta.json();
}

export async function listarPedidosAdmin() {
  const resposta = await fetch(`${API_URL}/pedidos`, {
    headers: headersComToken(),
  });

  if (!resposta.ok) {
    const erro = await resposta.json();
    throw new Error(erro.mensagem || 'Erro ao carregar pedidos');
  }

  return resposta.json();
}

export async function atualizarStatusOperacional(id, status_pedido) {
  const resposta = await fetch(`${API_URL}/pedidos/${id}/status-operacional`, {
    method: 'PATCH',
    headers: headersComToken(),
    body: JSON.stringify({ status_pedido }),
  });

  const dados = await resposta.json();
  if (!resposta.ok) throw new Error(dados.mensagem || 'Erro ao atualizar operação');
  return dados;
}

export async function atualizarCodigoRastreio(id, codigo_rastreio) {
  const resposta = await fetch(`${API_URL}/pedidos/${id}/rastreio`, {
    method: 'PATCH',
    headers: headersComToken(),
    body: JSON.stringify({ codigo_rastreio }),
  });

  const dados = await resposta.json();

  if (!resposta.ok) {
    throw new Error(dados.mensagem || 'Erro ao atualizar rastreio');
  }

  return dados;
}

export async function listarPedidosPorUsuario(usuarioId) {
  const token = localStorage.getItem('token');

  const resposta = await fetch(
    `${API_URL}/pedidos/usuario/${usuarioId}`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    }
  );

  const dados = await resposta.json();

  if (!resposta.ok) {
    throw new Error(dados.mensagem || 'Erro ao buscar pedidos do cliente');
  }

  return dados;
}

export async function buscarPedido(id) {
  const resposta = await fetch(`${API_URL}/pedidos/${id}`, {
    headers: headersComToken(),
  });

  const dados = await resposta.json();

  if (!resposta.ok) {
    throw new Error(dados.mensagem || 'Erro ao buscar pedido');
  }

  return dados;
}

