import { Navigate } from 'react-router-dom';
import { useAutenticacao } from '../contextos/ContextoAutenticacao';

export default function RotaPrivada({ children, somenteAdmin = false, somenteCliente = false }) {
  const { usuario, carregando } = useAutenticacao();

  if (carregando) {
    return <p className="text-center mt-10">Carregando...</p>;
  }

  if (!usuario) {
    return <Navigate to="/login" replace />;
  }

  if (somenteAdmin && usuario.perfil !== 'admin') {
    return <Navigate to="/" replace />;
  }

  if (somenteCliente && usuario.perfil === 'admin') {
    return <Navigate to="/admin" replace />;
  }

  return children;
}

import { Routes, Route } from 'react-router-dom';
import Login from '../paginas/publicas/Login';
import Cadastro from '../paginas/publicas/Cadastro';
import Home from '../paginas/publicas/Home';
import Carrinho from '../paginas/publicas/Carrinho';
import Checkout from '../paginas/publicas/Checkout';
import DetalheProduto from '../paginas/publicas/DetalheProduto';
import StatusPedido from '../paginas/publicas/StatusPedido';
import Painel from '../paginas/admin/Painel';
import Produtos from '../paginas/admin/Produtos';
import Pedidos from '../paginas/admin/Pedidos';
import Relatorios from '../paginas/admin/Relatorios';
import RotaPrivada from './RotaPrivada';
import ConfiguracaoLoja from '../paginas/admin/configuracaoLoja';
import Clientes from '../paginas/admin/Clientes';
import DetalheCliente from '../paginas/admin/DetalheCliente';
import DetalhePedido from '../paginas/admin/DetalhePedido';

export default function RotasApp() {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/login" element={<Login />} />
      <Route path="/cadastro" element={<Cadastro />} />
      <Route
        path="/carrinho"
        element={
          <RotaPrivada somenteCliente>
            <Carrinho />
          </RotaPrivada>
        }
      />
      <Route
        path="/checkout"
        element={
          <RotaPrivada somenteCliente>
            <Checkout />
          </RotaPrivada>
        }
      />
      <Route path="/produto/:id" element={<DetalheProduto />} />
      <Route path="/pedido/:id/:resultado" element={<StatusPedido />} />

      <Route
        path="/admin"
        element={
          <RotaPrivada somenteAdmin>
            <Painel />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/produtos"
        element={
          <RotaPrivada somenteAdmin>
            <Produtos />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/pedidos"
        element={
          <RotaPrivada somenteAdmin>
            <Pedidos />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/relatorios"
        element={
          <RotaPrivada somenteAdmin>
            <Relatorios />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/configuracoes"
        element={
          <RotaPrivada somenteAdmin>
            <ConfiguracaoLoja />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/clientes"
        element={
          <RotaPrivada somenteAdmin>
            <Clientes />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/clientes/:id"
        element={
          <RotaPrivada somenteAdmin>
            <DetalheCliente />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/pedidos/:id"
        element={
          <RotaPrivada somenteAdmin>
            <DetalhePedido />
          </RotaPrivada>
        }
      />
    </Routes>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { useCarrinho } from '../contextos/ContextoCarrinho';
import { useAutenticacao } from '../contextos/ContextoAutenticacao';

export default function CartaoProduto({ produto }) {
  const [adicionado, setAdicionado] = useState(false);
  const { adicionarItem } = useCarrinho();
  const { usuario } = useAutenticacao();

  function aoAdicionar() {
    adicionarItem(produto);
    setAdicionado(true);
    setTimeout(() => setAdicionado(false), 1200);
  }

  return (
    <div className="bg-white rounded-lg shadow hover:shadow-md transition p-4 flex flex-col">
      <Link to={`/produto/${produto.id}`}>
        <img
          src={produto.foto_url || 'https://placehold.co/200'}
          alt={produto.nome}
          className="w-full h-40 object-cover rounded mb-3"
        />
        <h2 className="font-semibold hover:text-blue-600">{produto.nome}</h2>
      </Link>
      <p className="text-sm text-gray-500 mb-2">{produto.categoria}</p>
      <p className="text-lg font-bold mb-3">
        {Number(produto.preco).toLocaleString('pt-BR', {
          style: 'currency',
          currency: 'BRL',
        })}
      </p>
      {usuario?.perfil !== 'admin' && (
        <button
          onClick={aoAdicionar}
          className={`mt-auto py-2 rounded transition ${
            adicionado ? 'bg-green-600 text-white' : 'bg-blue-600 text-white hover:bg-blue-700'
          }`}
        >
          {adicionado ? 'Adicionado!' : 'Adicionar ao carrinho'}
        </button>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAutenticacao } from '../../contextos/ContextoAutenticacao';
import { listarProdutos } from '../../servicos/produtoService';
import { buscarConfiguracoes } from '../../servicos/configuracaoService';
import CartaoProduto from '../../componentes/CartaoProduto';

export default function Home() {
  const [produtos, setProdutos] = useState([]);
  const [configuracoes, setConfiguracoes] = useState({});
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState('');
  const { usuario } = useAutenticacao();
  const navigate = useNavigate();

  useEffect(() => {
    if (usuario?.perfil === 'admin') navigate('/admin', { replace: true });
  }, [usuario, navigate]);

  useEffect(() => {
    async function carregar() {
      try {
        const [dadosProdutos, dadosConfiguracoes] = await Promise.all([
          listarProdutos(),
          buscarConfiguracoes(),
        ]);

        setProdutos(dadosProdutos);
        setConfiguracoes(dadosConfiguracoes);
      } catch (erro) {
        setErro(erro.message);
      } finally {
        setCarregando(false);
      }
    }

    carregar();
  }, []);

  if (carregando) {
    return <p className="text-center mt-10">Carregando produtos...</p>;
  }

  if (erro) {
    return <p className="text-center mt-10 text-red-600">{erro}</p>;
  }

  const banner = configuracoes.banner_url && (
    <img
      src={configuracoes.banner_url}
      alt={configuracoes.banner_titulo || 'Banner da loja'}
      className="w-full max-h-96 object-cover"
    />
  );

  return (
    <div>
      {configuracoes.aviso_ativo && configuracoes.aviso_texto && (
        <div className="bg-black text-white text-center px-4 py-2">
          {configuracoes.aviso_texto}
        </div>
      )}

      {configuracoes.banner_link ? (
        <a
          href={configuracoes.banner_link}
          target={configuracoes.banner_link.startsWith('http') ? '_blank' : undefined}
          rel={configuracoes.banner_link.startsWith('http') ? 'noreferrer' : undefined}
        >
          {banner}
        </a>
      ) : (
        banner
      )}

      <div className="max-w-6xl mx-auto px-4 py-8">
        <h1 className="text-2xl font-bold mb-6">Nossos produtos</h1>

        {produtos.length === 0 ? (
          <p className="text-gray-500">
            Nenhum produto disponível no momento.
          </p>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-6">
            {produtos.map((produto) => (
              <CartaoProduto key={produto.id} produto={produto} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  listarProdutosAdmin,
  criarProduto,
  atualizarProduto,
  removerProduto,
  reativarProduto,
} from '../../servicos/produtoService';

const FORM_VAZIO = {
  nome: '',
  categoria: '',
  preco: '',
  tag: '',
  foto_url: '',
  estoque_qtd: '',
};

export default function Produtos() {
  const [produtos, setProdutos] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState('');
  const [form, setForm] = useState(FORM_VAZIO);
  const [editandoId, setEditandoId] = useState(null);

  async function carregar() {
    try {
      setCarregando(true);
      const dados = await listarProdutosAdmin();
      setProdutos(dados);
    } catch (erro) {
      setErro(erro.message);
    } finally {
      setCarregando(false);
    }
  }

  useEffect(() => {
    carregar();
  }, []);

  function aoMudarCampo(e) {
    setForm({ ...form, [e.target.name]: e.target.value });
  }

  function iniciarEdicao(produto) {
    setEditandoId(produto.id);
    setForm({
      nome: produto.nome,
      categoria: produto.categoria || '',
      preco: produto.preco,
      tag: produto.tag || '',
      foto_url: produto.foto_url || '',
      estoque_qtd: produto.estoque_qtd,
    });
  }

  function cancelarEdicao() {
    setEditandoId(null);
    setForm(FORM_VAZIO);
  }

  async function aoSalvar(e) {
    e.preventDefault();
    setErro('');

    try {
      if (editandoId) {
        await atualizarProduto(editandoId, form);
      } else {
        await criarProduto(form);
      }

      cancelarEdicao();
      await carregar();
    } catch (erro) {
      setErro(erro.message);
    }
  }

  async function aoAlternarAtivo(produto) {
    try {
      if (produto.ativo) {
        await removerProduto(produto.id);
      } else {
        await reativarProduto(produto.id);
      }
      await carregar();
    } catch (erro) {
      setErro(erro.message);
    }
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <Link to="/admin" className="text-blue-600 hover:underline text-sm">
        &larr; Voltar ao painel
      </Link>

      <h1 className="text-2xl font-bold mt-2 mb-6">Produtos</h1>

      {erro && <p className="text-red-600 mb-4">{erro}</p>}

      <form onSubmit={aoSalvar} className="bg-white rounded-lg shadow p-4 mb-8 grid grid-cols-2 sm:grid-cols-3 gap-3">
        <input name="nome" value={form.nome} onChange={aoMudarCampo} placeholder="Nome" required className="border rounded px-2 py-1" />
        <input name="categoria" value={form.categoria} onChange={aoMudarCampo} placeholder="Categoria" className="border rounded px-2 py-1" />
        <input name="preco" value={form.preco} onChange={aoMudarCampo} placeholder="Preço" type="number" step="0.01" required className="border rounded px-2 py-1" />
        <input name="tag" value={form.tag} onChange={aoMudarCampo} placeholder="Tag" className="border rounded px-2 py-1" />
        <input name="foto_url" value={form.foto_url} onChange={aoMudarCampo} placeholder="URL da foto" className="border rounded px-2 py-1" />
        <input name="estoque_qtd" value={form.estoque_qtd} onChange={aoMudarCampo} placeholder="Estoque" type="number" required className="border rounded px-2 py-1" />

        <div className="col-span-2 sm:col-span-3 flex gap-2">
          <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
            {editandoId ? 'Salvar edição' : 'Adicionar produto'}
          </button>
          {editandoId && (
            <button type="button" onClick={cancelarEdicao} className="text-gray-600 px-4 py-2">
              Cancelar
            </button>
          )}
        </div>
      </form>

      {carregando ? (
        <p>Carregando produtos...</p>
      ) : (
        <table className="w-full bg-white rounded-lg shadow overflow-hidden">
          <thead className="bg-gray-100 text-left text-sm">
            <tr>
              <th className="p-3">Nome</th>
              <th className="p-3">Preço</th>
              <th className="p-3">Estoque</th>
              <th className="p-3">Status</th>
              <th className="p-3">Ações</th>
            </tr>
          </thead>
          <tbody>
            {produtos.map((produto) => (
              <tr key={produto.id} className="border-t text-sm">
                <td className="p-3">{produto.nome}</td>
                <td className="p-3">
                  {Number(produto.preco).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                </td>
                <td className="p-3">{produto.estoque_qtd}</td>
                <td className="p-3">
                  <span className={produto.ativo ? 'text-green-600' : 'text-gray-400'}>
                    {produto.ativo ? 'Ativo' : 'Inativo'}
                  </span>
                </td>
                <td className="p-3 flex gap-3">
                  <button onClick={() => iniciarEdicao(produto)} className="text-blue-600 hover:underline">
                    Editar
                  </button>
                  <button
                    onClick={() => aoAlternarAtivo(produto)}
                    className={produto.ativo
                      ? 'text-red-600 hover:underline'
                      : 'text-green-600 hover:underline'}
                  >
                    {produto.ativo ? 'Remover' : 'Reativar'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const test = require('node:test');
const request = require('supertest');
const app = require('../src/app');
const Usuario = require('../src/models/Usuario');
const pool = require('../src/config/banco');
const jwt = require('jsonwebtoken');
const usuariosTeste = [];
const produtosTeste = [];

async function criarUsuarioTeste(email, senha, perfil = 'cliente', status = 'ativo') {
  const id = await Usuario.criar({
    nome: 'Teste Usuário',
    email,
    senha,
    perfil,
    cpf: '123.456.789-09',
  });

  await pool.query(
    'UPDATE usuarios SET status = ? WHERE id = ?',
    [status, id]
  );

  usuariosTeste.push(id);
  return { id, email, senha };
}

test.after(async () => {
  if (usuariosTeste.length) {
    const [pedidos] = await pool.query(
      'SELECT id FROM pedidos WHERE usuario_id IN (?)',
      [usuariosTeste]
    );
    const pedidosIds = pedidos.map((pedido) => pedido.id);

    if (pedidosIds.length) {
      await pool.query('DELETE FROM itens_pedido WHERE pedido_id IN (?)', [pedidosIds]);
      await pool.query('DELETE FROM pedidos WHERE id IN (?)', [pedidosIds]);
    }

    await pool.query('DELETE FROM usuarios WHERE id IN (?)', [usuariosTeste]);
  }

  if (produtosTeste.length) {
    await pool.query('DELETE FROM produtos WHERE id IN (?)', [produtosTeste]);
  }
  await pool.end();
});

test('login deve bloquear usuário inativo', async () => {
  const email = `bloqueado-${Date.now()}@teste.com`;
  await criarUsuarioTeste(email, 'senha123', 'cliente', 'bloqueado');

  const resposta = await request(app)
    .post('/api/auth/login')
    .send({ email, senha: 'senha123' });

  assert.equal(resposta.status, 403);
  assert.match(resposta.body.mensagem, /bloqueado/i);
});

test('login deve gerar token para usuário ativo', async () => {
  const email = `ativo-${Date.now()}@teste.com`;
  await criarUsuarioTeste(email, 'senha123', 'cliente', 'ativo');

  const resposta = await request(app)
    .post('/api/auth/login')
    .send({ email, senha: 'senha123' });

  assert.equal(resposta.status, 200);
  assert.ok(resposta.body.token);
  assert.equal(resposta.body.usuario.email, undefined);
  assert.equal(resposta.body.usuario.perfil, 'cliente');
});

test('pedido de outro cliente deve ser bloqueado', async () => {
  const dono = await criarUsuarioTeste(`dono-${Date.now()}@teste.com`, 'senha123');
  const intruso = await criarUsuarioTeste(`intruso-${Date.now()}@teste.com`, 'senha123');

  const [pedido] = await pool.query(
    'INSERT INTO pedidos (usuario_id, tipo_entrega, endereco_entrega, telefone_contato, total) VALUES (?, ?, ?, ?, ?)',
    [dono.id, 'envio', 'Rua A, 123', '(61)99999-9999', 50.00]
  );

  const token = jwt.sign({ id: intruso.id, perfil: 'cliente' }, process.env.JWT_SECRET, { expiresIn: '1h' });

  const resposta = await request(app)
    .get(`/api/pedidos/${pedido.insertId}`)
    .set('Authorization', `Bearer ${token}`);

  assert.equal(resposta.status, 403);
  assert.match(resposta.body.mensagem, /acesso/i);
});

test('webhook deve rejeitar assinatura inválida', async () => {
  process.env.MERCADOPAGO_WEBHOOK_SECRET = 'segredo-teste';

  const resposta = await request(app)
    .post('/api/pagamentos/webhook?data.id=123&type=payment')
    .set('x-signature', 'assinatura-invalida')
    .type('json')
    .send({ id: 'evt_123' });

  assert.equal(resposta.status, 401);
  assert.match(resposta.text, /assinatura|webhook/i);
});

test('webhook deve validar assinatura correta antes de processar', async () => {
  process.env.MERCADOPAGO_WEBHOOK_SECRET = 'segredo-teste';

  const payload = JSON.stringify({ id: 'evt_123' });
  const assinatura = crypto.createHmac('sha256', process.env.MERCADOPAGO_WEBHOOK_SECRET)
    .update(payload)
    .digest('hex');

  const resposta = await request(app)
    .post('/api/pagamentos/webhook?data.id=123&type=payment')
    .set('x-signature', assinatura)
    .type('json')
    .send(JSON.parse(payload));

  assert.notEqual(resposta.status, 401);
});

test('cliente pode cancelar pedido e receber estoque de volta', async () => {
  const usuario = await criarUsuarioTeste(`cancel-${Date.now()}@teste.com`, 'senha123');
  const token = jwt.sign({ id: usuario.id, perfil: 'cliente' }, process.env.JWT_SECRET, { expiresIn: '1h' });

  const [produto] = await pool.query(
    'INSERT INTO produtos (nome, categoria, preco, tag, foto_url, estoque_qtd, ativo) VALUES (?, ?, ?, ?, ?, ?, ?)',
    ['Produto Cancelamento', 'Acessórios', 49.90, 'promo', 'https://img.test/produto.jpg', 3, true]
  );
  produtosTeste.push(produto.insertId);

  const [pedido] = await pool.query(
    'INSERT INTO pedidos (usuario_id, payment_status, payment_id, tipo_entrega, endereco_entrega, telefone_contato, total) VALUES (?, ?, ?, ?, ?, ?, ?)',
    [usuario.id, 'pago', 'pay_123', 'envio', 'Rua B, 456', '(61)98888-7777', 99.80]
  );

  await pool.query(
    'INSERT INTO itens_pedido (pedido_id, produto_id, quantidade, preco_unitario) VALUES (?, ?, ?, ?)',
    [pedido.insertId, produto.insertId, 2, 49.90]
  );

  const resposta = await request(app)
    .patch(`/api/pedidos/${pedido.insertId}/cancelar`)
    .set('Authorization', `Bearer ${token}`);

  assert.equal(resposta.status, 200);
  assert.match(resposta.body.mensagem, /cancelado/i);

  const [pedidoAtualizado] = await pool.query('SELECT payment_status FROM pedidos WHERE id = ?', [pedido.insertId]);
  const [estoqueAtualizado] = await pool.query('SELECT estoque_qtd FROM produtos WHERE id = ?', [produto.insertId]);

  assert.equal(pedidoAtualizado[0].payment_status, 'cancelado');
  assert.equal(Number(estoqueAtualizado[0].estoque_qtd), 5);
});

test('criação de pedido é idempotente e não duplica reserva de estoque', async () => {
  const usuario = await criarUsuarioTeste(`idempotente-${Date.now()}@teste.com`, 'senha123');
  const token = jwt.sign({ id: usuario.id, perfil: 'cliente' }, process.env.JWT_SECRET, { expiresIn: '1h' });

  const [produto] = await pool.query(
    'INSERT INTO produtos (nome, categoria, preco, estoque_qtd, ativo) VALUES (?, ?, ?, ?, ?)',
    ['Produto Idempotência', 'Testes', 25.00, 4, true]
  );
  produtosTeste.push(produto.insertId);

  const payload = {
    tipo_entrega: 'entrega_local',
    endereco_entrega: 'Rua Idempotência, 10',
    telefone_contato: '(61)99999-1111',
    itens: [{ produto_id: produto.insertId, quantidade: 2, preco_unitario: 25 }],
  };
  const chave = `teste-${Date.now()}`;

  const primeira = await request(app)
    .post('/api/pedidos')
    .set('Authorization', `Bearer ${token}`)
    .set('Idempotency-Key', chave)
    .send(payload);

  const segunda = await request(app)
    .post('/api/pedidos')
    .set('Authorization', `Bearer ${token}`)
    .set('Idempotency-Key', chave)
    .send(payload);

  assert.equal(primeira.status, 201);
  assert.equal(segunda.status, 200);
  assert.equal(segunda.body.id, primeira.body.id);

  const [pedidos] = await pool.query(
    'SELECT COUNT(*) AS quantidade FROM pedidos WHERE id = ?',
    [primeira.body.id]
  );
  const [estoque] = await pool.query(
    'SELECT estoque_qtd FROM produtos WHERE id = ?',
    [produto.insertId]
  );

  assert.equal(Number(pedidos[0].quantidade), 1);
  assert.equal(Number(estoque[0].estoque_qtd), 2);

  await pool.query('DELETE FROM itens_pedido WHERE pedido_id = ?', [primeira.body.id]);
  await pool.query('DELETE FROM pedidos WHERE id = ?', [primeira.body.id]);
  await pool.query('DELETE FROM produtos WHERE id = ?', [produto.insertId]);
  await pool.query('DELETE FROM usuarios WHERE id = ?', [usuario.id]);
});

test('status operacional respeita a ordem de expedição', async () => {
  const admin = await criarUsuarioTeste(`admin-status-${Date.now()}@teste.com`, 'senha123', 'admin');
  const cliente = await criarUsuarioTeste(`cliente-status-${Date.now()}@teste.com`, 'senha123');
  const token = jwt.sign({ id: admin.id, perfil: 'admin' }, process.env.JWT_SECRET, { expiresIn: '1h' });

  const [pedido] = await pool.query(
    `INSERT INTO pedidos
      (usuario_id, idempotency_key, payment_status, status_pedido, tipo_entrega,
       endereco_entrega, telefone_contato, subtotal, total)
     VALUES (?, ?, 'pago', 'pago', 'entrega_local', ?, ?, ?, ?)`,
    [cliente.id, `status-${Date.now()}`, 'Rua Status, 1', '(61)99999-2222', 30, 30]
  );

