import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { listarPedidosAdmin, atualizarStatusOperacional } from '../../servicos/pedidoService';

const TRANSICOES = {
  pago: ['em_preparacao', 'cancelado'],
  em_preparacao: ['enviado', 'cancelado'],
  enviado: ['entregue'],
  reembolso_pendente: ['reembolsado'],
};

const STATUS_CORES = {
  aguardando_pagamento: 'text-yellow-600',
  pago: 'text-green-600',
  em_preparacao: 'text-blue-600',
  enviado: 'text-blue-600',
  entregue: 'text-green-700',
  cancelado: 'text-gray-400',
  reembolso_pendente: 'text-yellow-600',
  reembolsado: 'text-gray-500',
};

const STATUS_LABELS = {
  aguardando_pagamento: 'Aguardando confirmação',
  pendente: 'Pendente',
  pago: 'Pagamento aprovado',
  recusado: 'Pagamento recusado',
  cancelado: 'Cancelado',
  em_preparacao: 'Em preparação',
  enviado: 'Enviado',
  entregue: 'Entregue',
  reembolso_pendente: 'Reembolso em processamento',
  reembolsado: 'Reembolso concluído',
};

export default function Pedidos() {
  const [pedidos, setPedidos] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState('');

  async function carregar() {
    try {
      setCarregando(true);
      const dados = await listarPedidosAdmin();
      setPedidos(dados);
    } catch (erro) {
      setErro(erro.message);
    } finally {
      setCarregando(false);
    }
  }

  useEffect(() => {
    carregar();
  }, []);

  async function aoMudarStatus(pedidoId, novoStatus) {
    try {
      await atualizarStatusOperacional(pedidoId, novoStatus);
      await carregar();
    } catch (erro) {
      setErro(erro.message);
    }
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <Link to="/admin" className="text-blue-600 hover:underline text-sm">
        &larr; Voltar ao painel
      </Link>

      <h1 className="text-2xl font-bold mt-2 mb-6">Pedidos</h1>

      {erro && <p className="text-red-600 mb-4">{erro}</p>}

      {carregando ? (
        <p>Carregando pedidos...</p>
      ) : (
        <table className="w-full bg-white rounded-lg shadow overflow-hidden">
          <thead className="bg-gray-100 text-left text-sm">
            <tr>
              <th className="p-3">Cliente</th>
              <th className="p-3">Total</th>
              <th className="p-3">Data</th>
              <th className="p-3">Pagamento</th>
              <th className="p-3">Operação</th>
            </tr>
          </thead>
          <tbody>
            {pedidos.map((pedido) => (
              <tr key={pedido.id} className="border-t text-sm">
                <td className="p-3">
                  <p>{pedido.usuario_nome}</p>
                  <p className="text-gray-400 text-xs">{pedido.usuario_email}</p>
                </td>
                <td className="p-3">
                  {Number(pedido.total).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                </td>
                <td className="p-3">
                  {new Date(pedido.criado_em).toLocaleDateString('pt-BR')}
                </td>
                <td className="p-3">{STATUS_LABELS[pedido.payment_status] || pedido.payment_status}</td>
                <td className="p-3">
                  {(() => {
                    const opcoes = TRANSICOES[pedido.status_pedido] || [];
                    return (
                  <select
                    value=""
                    disabled={opcoes.length === 0}
                    onChange={(e) => aoMudarStatus(pedido.id, e.target.value)}
                    className={`border rounded px-2 py-1 bg-white ${STATUS_CORES[pedido.status_pedido] || ''}`}
                  >
                    <option value="">{STATUS_LABELS[pedido.status_pedido] || 'Sem status'}</option>
                    {opcoes.map((status) => (
                      <option key={status} value={status}>
                        {STATUS_LABELS[status] || status}
                      </option>
                    ))}
                  </select>
                    );
                  })()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useCarrinho } from '../../contextos/ContextoCarrinho';
import { useAutenticacao } from '../../contextos/ContextoAutenticacao';
import { buscarPedido } from '../../servicos/pedidoService';

const API_URL = import.meta.env.VITE_API_URL || '/api';

const CONTEUDO = {
  sucesso: {
    titulo: 'Pagamento aprovado!',
    mensagem: 'Seu pedido foi confirmado e já está sendo preparado.',
    cor: 'text-green-600',
  },
  pendente: {
    titulo: 'Pagamento em análise',
    mensagem: 'Assim que for confirmado, seu pedido será processado.',
    cor: 'text-yellow-600',
  },
  falha: {
    titulo: 'Pagamento não concluído',
    mensagem: 'Algo deu errado ou a compra foi cancelada. Você pode tentar novamente.',
    cor: 'text-red-600',
  },
};

export default function StatusPedido() {
  const { id, resultado } = useParams();
  const { limparCarrinho } = useCarrinho();
  const { token } = useAutenticacao();
  const sincronizado = useRef(false);
  const pedidoAtualRef = useRef(null);
  const [pedido, setPedido] = useState(null);
  const [erroPedido, setErroPedido] = useState('');

  const conteudo = CONTEUDO[resultado] || CONTEUDO.falha;

  useEffect(() => {
    if (resultado === 'sucesso') {
      limparCarrinho();
    }

    async function carregarPedido() {
      if (!token) return;
      try {
        const dados = await buscarPedido(id);
        pedidoAtualRef.current = dados;
        setPedido(dados);
        setErroPedido('');
      } catch (erro) {
        setErroPedido(erro.message);
      }
    }

    if (resultado === 'sucesso' || resultado === 'falha') {
      const parametros = new URLSearchParams(window.location.search);
      const paymentId = parametros.get('payment_id') || parametros.get('collection_id');
      if (paymentId && token && !sincronizado.current) {
        sincronizado.current = true;
        fetch(`${API_URL}/pagamentos/${id}/sincronizar`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ payment_id: paymentId }),
        }).catch(() => {}).finally(carregarPedido);
      } else {
        carregarPedido();
      }
    } else {
      carregarPedido();
    }

    const intervalo = setInterval(() => {
      if (!pedidoAtualRef.current || ['entregue', 'cancelado', 'reembolsado'].includes(pedidoAtualRef.current.status_pedido)) return;
      carregarPedido();
    }, 10000);

    return () => clearInterval(intervalo);
  }, [resultado, limparCarrinho, id, token]);

  const etapas = [
    ['aguardando_pagamento', 'Aguardando confirmação do pagamento'],
    ['pago', 'Pagamento aprovado'],
    ['em_preparacao', 'Em preparação'],
    ['enviado', 'Enviado'],
    ['entregue', 'Entregue'],
  ];
  const etapaAtual = etapas.findIndex(([status]) => status === pedido?.status_pedido);

  return (
    <div className="max-w-md mx-auto px-4 py-16 text-center">
      <h1 className={`text-2xl font-bold mb-3 ${conteudo.cor}`}>{conteudo.titulo}</h1>
      <p className="text-gray-600 mb-2">{conteudo.mensagem}</p>
      <p className="text-sm text-gray-400 mb-6">Pedido #{id}</p>

      {erroPedido && <p className="text-sm text-red-600 mb-4">{erroPedido}</p>}

      {pedido && (
        <div className="text-left bg-white border rounded-lg p-5 mb-6">
          <p className="font-semibold mb-4">Acompanhamento</p>
          <ol className="space-y-3">
            {etapas.map(([status, titulo], indice) => (
              <li key={status} className={indice <= etapaAtual ? 'text-green-600' : 'text-gray-400'}>
                <span className="inline-block w-5">{indice <= etapaAtual ? '✓' : '○'}</span>
                {titulo}
              </li>
            ))}
          </ol>
          {pedido.status_pedido === 'cancelado' && (
            <p className="text-red-600 mt-4">Pedido cancelado.</p>
          )}
          {pedido.status_pedido === 'reembolso_pendente' && (
            <p className="text-yellow-600 mt-4">Reembolso em processamento.</p>
          )}
          {pedido.codigo_rastreio && (
            <p className="mt-4 text-sm">Código de rastreio: <strong>{pedido.codigo_rastreio}</strong></p>
          )}
        </div>
      )}

      <Link to="/" className="text-blue-600 hover:underline">
        Voltar para a loja
      </Link>
    </div>
  );
}

