      <Route
        path="/admin"
        element={
          <RotaPrivada somenteAdmin>
            <Painel />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/produtos"
        element={
          <RotaPrivada somenteAdmin>
            <Produtos />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/pedidos"
        element={
          <RotaPrivada somenteAdmin>
            <Pedidos />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/relatorios"
        element={
          <RotaPrivada somenteAdmin>
            <Relatorios />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/configuracoes"
        element={
          <RotaPrivada somenteAdmin>
            <ConfiguracaoLoja />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/promocoes"
        element={
          <RotaPrivada somenteAdmin>
            <Promocoes />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/clientes"
        element={
          <RotaPrivada somenteAdmin>
            <Clientes />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/clientes/:id"
        element={
          <RotaPrivada somenteAdmin>
            <DetalheCliente />
          </RotaPrivada>
        }
      />
      <Route
        path="/admin/pedidos/:id"
        element={
          <RotaPrivada somenteAdmin>
            <DetalhePedido />
          </RotaPrivada>
        }
      />
    </Routes>
  );
}

