      });
    }

    await Log.registrar({
      tipo: 'pedido',
      acao: 'rastreio_atualizado',
      entidade_id: req.params.id,
      usuario_id: req.usuario.id,
      detalhes: { codigo_rastreio },
    });

    res.json({ mensagem: 'Código de rastreio atualizado' });
  } catch (erro) {
