const pool = require('../config/banco');

async function buscar(req, res) {
  try {
    const [linhas] = await pool.execute(
      'SELECT * FROM configuracoes_loja WHERE id = 1'
    );

    res.json(linhas[0] || {});
  } catch (erro) {
    console.error('Erro ao buscar configurações:', erro);
    res.status(500).json({ mensagem: 'Erro ao buscar configurações' });
  }
}

async function atualizar(req, res) {
  const {
    whatsapp = '',
    email_suporte = '',
    aviso_ativo = false,
    aviso_texto = '',
    politica_devolucao = '',
    banner_url = '',
    banner_titulo = '',
    banner_link = '',
  } = req.body;

  try {
    await pool.execute(
      `UPDATE configuracoes_loja
       SET whatsapp = ?, email_suporte = ?, aviso_ativo = ?,
           aviso_texto = ?, politica_devolucao = ?,
           banner_url = ?, banner_titulo = ?, banner_link = ?
       WHERE id = 1`,
      [
        String(whatsapp).trim(),
        String(email_suporte).trim(),
        Boolean(aviso_ativo),
        String(aviso_texto).trim(),
        String(politica_devolucao).trim(),
        String(banner_url).trim(),
        String(banner_titulo).trim(),
        String(banner_link).trim(),
      ]
    );

    res.json({ mensagem: 'Configurações atualizadas com sucesso' });
  } catch (erro) {
    console.error('Erro ao atualizar configurações:', erro);
    res.status(500).json({ mensagem: 'Erro ao atualizar configurações' });
  }
}

module.exports = { buscar, atualizar };

import { useEffect, useState } from 'react';
import {
  buscarConfiguracoes,
  atualizarConfiguracoes,
} from '../../servicos/configuracaoService';

const inicial = {
  whatsapp: '',
  email_suporte: '',
  aviso_ativo: false,
  aviso_texto: '',
  politica_devolucao: '',
  banner_url: '',
  banner_titulo: '',
  banner_link: '',
};

export default function ConfiguracaoLoja() {
  const [formulario, setFormulario] = useState(inicial);
  const [mensagem, setMensagem] = useState('');
  const [carregando, setCarregando] = useState(true);
  const [salvando, setSalvando] = useState(false);

  useEffect(() => {
    async function carregar() {
      try {
        const dados = await buscarConfiguracoes();

        setFormulario({
          ...inicial,
          ...dados,
          aviso_ativo: Boolean(dados.aviso_ativo),
        });
      } catch (erro) {
        setMensagem(erro.message);
      } finally {
        setCarregando(false);
      }
    }

    carregar();
  }, []);

  function alterar(evento) {
    const { name, value, type, checked } = evento.target;

    setFormulario((anterior) => ({
      ...anterior,
      [name]: type === 'checkbox' ? checked : value,
    }));
  }

  async function salvar(evento) {
    evento.preventDefault();
    setMensagem('');
    setSalvando(true);

    try {
      await atualizarConfiguracoes(formulario);
      setMensagem('Configurações salvas com sucesso.');
    } catch (erro) {
      setMensagem(erro.message);
    } finally {
      setSalvando(false);
    }
  }

  if (carregando) {
    return <p className="text-center mt-10">Carregando configurações...</p>;
  }

  return (
    <div className="max-w-3xl mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold mb-6">Configurações da loja</h1>

      <form
        onSubmit={salvar}
        className="bg-white rounded-lg shadow p-6 space-y-4"
      >
        <input
          type="tel"
          name="whatsapp"
          value={formulario.whatsapp}
          onChange={alterar}
          placeholder="WhatsApp de suporte"
          className="w-full border p-2 rounded"
        />

        <input
          type="email"
          name="email_suporte"
          value={formulario.email_suporte}
          onChange={alterar}
          placeholder="E-mail de suporte"
          className="w-full border p-2 rounded"
        />

        <label className="flex items-center gap-2">
          <input
            type="checkbox"
            name="aviso_ativo"
            checked={formulario.aviso_ativo}
            onChange={alterar}
          />
          Exibir aviso no topo da loja
        </label>

        <input
          type="text"
          name="aviso_texto"
          value={formulario.aviso_texto}
          onChange={alterar}
          placeholder="Texto do aviso"
          className="w-full border p-2 rounded"
        />

        <input
          type="url"
          name="banner_url"
          value={formulario.banner_url}
          onChange={alterar}
